/* From Uiverse.io by andrew-demchenk0 - Tags: radio, stars, rating */
.__UIV_SCOPE__ .rating:not(:checked) > input {
  position: absolute;
  appearance: none;
}

.__UIV_SCOPE__ .rating:not(:checked) > label {
  float: right;
  cursor: pointer;
  font-size: 30px;
  color: #666;
}

.__UIV_SCOPE__ .rating:not(:checked) > label:before {
  content: '★';
}

.__UIV_SCOPE__ .rating > input:checked + label:hover,
.__UIV_SCOPE__ .rating > input:checked + label:hover ~ label,
.__UIV_SCOPE__ .rating > input:checked ~ label:hover,
.__UIV_SCOPE__ .rating > input:checked ~ label:hover ~ label,
.__UIV_SCOPE__ .rating > label:hover ~ input:checked ~ label {
  color: #e58e09;
}

.__UIV_SCOPE__ .rating:not(:checked) > label:hover,
.__UIV_SCOPE__ .rating:not(:checked) > label:hover ~ label {
  color: #ff9e0b;
}

.__UIV_SCOPE__ .rating > input:checked ~ label {
  color: #ffa723;
}
